<script>
  (() => {
    const trips = @json($tripDetails);
    trips.forEach(trip=>{const card=[...document.querySelectorAll('.trip-data-card')].find(item=>item.querySelector('h3')?.textContent.trim()===trip.code);const products=trip.products||[];const start=products.length?Math.min(...products.map(item=>Number(item.price)||0)):null;if(card&&!card.querySelector('.trip-preview-image')){card.insertAdjacentHTML('afterbegin',`${trip.image?`<img class="trip-preview-image" src="${trip.image}" alt="Produk jastip ${trip.traveler}">`:''}<div class="trip-preview-copy"><strong>${trip.traveler}</strong> · ${products.length} produk tersedia</div>${start!==null?`<div class="trip-starting-price">Mulai dari Rp ${start.toLocaleString('id-ID')}</div>`:''}`);}});
    const modal=document.getElementById('trip-detail-modal'); const content=document.getElementById('trip-detail-content'); const close=modal?.querySelector('.po-close'); const closeAction=modal?.querySelector('[data-detail-close]'); const hide=()=>{modal?.classList.remove('is-open');document.body.style.overflow='';}; close?.addEventListener('click',hide); closeAction?.addEventListener('click',hide); modal?.addEventListener('click',event=>{if(event.target===modal)hide();}); document.addEventListener('keydown',event=>{if(event.key==='Escape'&&modal?.classList.contains('is-open'))hide();});
    const open=card=>{const trip=trips.find(item=>item.code===card.querySelector('h3')?.textContent.trim());if(!trip)return;const products=trip.products||[];const productList=products.length?products.map(item=>`<article class="trip-product-item"><header><strong>${item.name}</strong><span class="trip-product-price">Rp ${Number(item.price||0).toLocaleString('id-ID')}</span></header><p>${item.description||'Detail produk belum ditambahkan.'}</p></article>`).join(''):'<p>Traveler belum menambahkan daftar produk jastip.</p>';content.innerHTML=`<div class="trip-detail-grid"><div class="trip-detail-item"><small>Traveler</small><strong>${trip.traveler}</strong><span style="display:block;margin-top:3px;color:var(--muted);font-size:11px">${trip.email}</span></div><div class="trip-detail-item"><small>Rute</small><strong>${trip.origin} → ${trip.destination}</strong></div><div class="trip-detail-item"><small>Berangkat</small><strong>${trip.departure||'Belum diatur'}</strong></div><div class="trip-detail-item"><small>Tiba</small><strong>${trip.arrival||'Belum diatur'}</strong></div><div class="trip-detail-item"><small>DP</small><strong>${trip.dpRequired ? trip.dp+'%' : 'Tanpa DP'}</strong></div></div><div class="trip-product"><h3>Produk jastip yang tersedia</h3><div class="trip-product-list">${productList}</div>${trip.image?`<img class="trip-product-image" src="${trip.image}" alt="Contoh produk jastip dari ${trip.traveler}">`:''}</div>`;modal.classList.add('is-open');document.body.style.overflow='hidden';close?.focus();};
    document.querySelectorAll('.trip-data-card').forEach(card=>{card.setAttribute('role','button');card.setAttribute('tabindex','0');card.setAttribute('aria-label','Lihat detail '+(card.querySelector('h3')?.textContent.trim()||'perjalanan'));card.addEventListener('click',()=>open(card));card.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();open(card);}});});
    window.addEventListener('request-trip-details', event=>{window.selectedTrip=event.detail;const orderLink=document.getElementById('trip-detail-order');if(orderLink)orderLink.href=`/orders/create?trip_reference=${encodeURIComponent(event.detail.code)}`;const card=[...document.querySelectorAll('.trip-data-card')].find(item=>item.querySelector('h3')?.textContent.trim()===event.detail.code);if(card)card.click();});document.getElementById('trip-detail-chat')?.addEventListener('click',()=>{if(window.selectedTrip)window.dispatchEvent(new CustomEvent('open-trip-chat',{detail:window.selectedTrip}));});
  })();
