    const trips = @json($tripDetails); const role = @json(auth()->user()->role?->name); const modal = document.getElementById('trip-chat-modal'); const messages = document.getElementById('trip-chat-messages'); const form = document.getElementById('trip-chat-form'); const input = document.getElementById('trip-chat-input'); let activeTrip = null; let activeConversation = null;
    const render = list => { messages.textContent=''; if (!list?.length) { messages.innerHTML='<div class="chat-empty">Belum ada pesan. Mulai percakapan.</div>'; return; } list.forEach(item=>{const bubble=document.createElement('div');bubble.className=`chat-bubble${Number(item.sender_id)===Number({{ auth()->id() }})?' mine':''}`;bubble.textContent=item.body;const meta=document.createElement('small');meta.textContent=item.sender?.name||'Pengguna';bubble.appendChild(meta);messages.appendChild(bubble);});messages.scrollTop=messages.scrollHeight; };
    const load = async trip => { const response=await fetch(`/trips/${trip.id}/chat`,{headers:{Accept:'application/json'}});if(!response.ok){window.showToast?.('Chat tidak tersedia.','error');return;}const data=await response.json();if(role==='TRAVELER'){const conversation=data.conversations?.[0];activeConversation=conversation?.id||null;render(conversation?.messages||[]);document.getElementById('trip-chat-subtitle').textContent=conversation?`Chat dengan ${conversation.customer?.name||'pelanggan'}`:'Belum ada pelanggan yang menghubungi.';}else{activeConversation=data.conversation?.id||null;render(data.conversation?.messages||[]);document.getElementById('trip-chat-subtitle').textContent=`Chat dengan ${trip.traveler||'traveler'}`;}};
    const open = async trip => {activeTrip=trip;document.getElementById('trip-chat-title').textContent=`Chat · ${trip.code}`;messages.innerHTML='<div class="chat-empty">Memuat percakapan…</div>';modal.classList.add('is-open');document.body.style.overflow='hidden';await load(trip);input.focus();};
    document.querySelectorAll('.trip-data-card').forEach(card=>{const trip=trips.find(item=>item.code===card.querySelector('h3')?.textContent.trim());if(!trip)return;const button=document.createElement('button');button.type='button';button.className='btn btn-outline btn-sm';button.style.cssText='width:100%;justify-content:center;margin-top:auto';button.innerHTML='<i class="bi bi-eye"></i> View details';button.addEventListener('click',event=>{event.stopPropagation();window.dispatchEvent(new CustomEvent('request-trip-details',{detail:trip}));});card.appendChild(button);});
    form?.addEventListener('submit',async event=>{event.preventDefault();if(!activeTrip)return;const body=input.value.trim();if(!body)return;const response=await fetch(`/trips/${activeTrip.id}/chat`,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify({body,conversation_id:activeConversation})});if(!response.ok){window.showToast?.('Pesan gagal dikirim.','error');return;}const data=await response.json();if(data.message){activeConversation ||= data.message.conversation_id;input.value='';await load(activeTrip);}});
    const hide=()=>{modal?.classList.remove('is-open');document.body.style.overflow='';};modal?.querySelector('.chat-close')?.addEventListener('click',hide);modal?.addEventListener('click',event=>{if(event.target===modal)hide();});document.addEventListener('keydown',event=>{if(event.key==='Escape')hide();});window.addEventListener('open-trip-chat',event=>open(event.detail));setInterval(()=>{if(modal?.classList.contains('is-open')&&activeTrip)load(activeTrip);},5000);
  })();
</script>
@endsection
